const input = $input.first().json;
const submitted = Array.isArray(input.body) ? input.body : input.body?.articles ?? [input.body];
if (!Array.isArray(submitted) || !submitted.length || submitted.length > 250) {
  throw new Error('Submit one article or a batch of up to 250 articles');
}

const normalize = value => String(value ?? '').normalize('NFKC').trim().toLowerCase();
const titleKey = value => normalize(value).replace(/[^\p{L}\p{N}]+/gu,' ').trim();
function articleOf(value) {
  const id = String(value?.article_id ?? value?.$id ?? '').trim();
  const headline = String(value?.headline ?? '').trim();
  const language = normalize(value?.language);
  const date = String(value?.date ?? '');
  const permalink = new URL(value?.permalink ?? '');
  if (!id || !headline || !['en','de','nl'].includes(language) ||
      !Number.isFinite(Date.parse(date)) || permalink.protocol !== 'https:') {
    throw new Error('Each article needs an ID, headline, supported language, publication date, and HTTPS permalink');
  }
  // Keep the original URL for readers. Remove tracking only for deduplication.
  const canonical = new URL(permalink);
  for (const key of [...canonical.searchParams.keys()]) {
    if (/^(utm_|fbclid$|gclid$)/i.test(key)) canonical.searchParams.delete(key);
  }
  canonical.hash = '';
  canonical.searchParams.sort();
  return {
    article_id:id, headline, language, date, permalink:permalink.href,
    canonical_url:canonical.href,
    publisher:normalize(value.publisher?.name ?? value.publisher_name ?? value.publication?.name),
    author:normalize(value.author ?? value.source),
    event_id:String(value.event_id ?? '').trim(),
    translation_group_id:String(value.translation_group_id ?? '').trim(),
    provider_categories:Array.isArray(value.provider_categories) ? value.provider_categories : [],
    excerpt:typeof value.excerpt === 'string' ? value.excerpt : '',
    text_content:typeof value.text_content === 'string' ? value.text_content : '',
  };
}

const articles = [];
const ids = new Set();
const urls = new Set();
for (const entry of submitted) {
  const article = articleOf(entry);
  const articleKey = article.language + '|' + article.article_id;
  const urlKey = article.language + '|' + article.canonical_url;
  if (ids.has(articleKey) || urls.has(urlKey)) continue;
  ids.add(articleKey);
  urls.add(urlKey);
  articles.push(article);
}

const parents = articles.map((_,i) => i);
const find = i => parents[i] === i ? i : (parents[i] = find(parents[i]));
const join = (a,b) => { parents[find(b)] = find(a); };
const matches = new Map();
const maxMatchingAge = 86400000;
articles.forEach((article, i) => {
  const keys = [];
  if (article.event_id) keys.push('event|' + article.event_id);
  if (article.translation_group_id && article.publisher) {
    keys.push('translation|' + article.publisher + '|' + article.translation_group_id);
  }
  const normalizedTitle = titleKey(article.headline);
  if (normalizedTitle.length >= 22) keys.push('title|' + article.language + '|' + normalizedTitle);
  for (const key of keys) {
    for (const other of matches.get(key) ?? []) {
      const prior = articles[other];
      if (key.startsWith('title|') &&
          (Math.abs(Date.parse(prior.date) - Date.parse(article.date)) > maxMatchingAge ||
           (prior.event_id && article.event_id && prior.event_id !== article.event_id))) continue;
      join(i,other);
    }
    matches.set(key,[...(matches.get(key) ?? []),i]);
  }
});

const groups = new Map();
articles.forEach((article,i) => groups.set(find(i),[...(groups.get(find(i)) ?? []),article]));
const stories = [...groups.values()].map(sources => {
  const language_editions = {};
  for (const source of sources) {
    const {article_id,headline,permalink,date,publisher} = source;
    (language_editions[source.language] ??= []).push({article_id,headline,permalink,date,publisher});
  }
  return {event_id:sources.find(a=>a.event_id)?.event_id || null, language_editions, sources};
});
return [{json:{api_base_url:input.api_base_url,batch:{articles_received:submitted.length,stories}}}];
